def longest_unique_span(text):
    n = len(text)
    if n == 0:
        return ""
    last_seen = {}
    left = 0
    best_start = 0
    best_len = 0
    for right in range(n):
        ch = text[right]
        if ch in last_seen and last_seen[ch] >= left:
            left = last_seen[ch] + 1
        last_seen[ch] = right
        cur_len = right - left + 1
        if cur_len > best_len:
            best_len = cur_len
            best_start = left
    return text[best_start:best_start + best_len]
